 60	/// Retains the protocol spelling; aliases name a distribution and relative paths name a directory.
 61	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
 62	#[serde(rename_all = "camelCase")]
 63	pub struct WorkspaceSpec {
 64	    pub kind: WorkspaceKind,
 65	    pub suffix: String,
 66	}
 67	
 68	impl WorkspaceSpec {
 69	    pub fn alias(&self) -> Option<&str> {
 70	        if self.relative_path().is_some() {
 71	            return None;
 72	        }
 73	        self.suffix
 74	            .rsplit_once('@')
 75	            .and_then(|(name, _)| (!name.is_empty() && !name.contains([':', ' ', '\\'])).then_some(name))
 76	    }
 77	
 78	    /// Bind this directory relative to the declaring manifest to an admitted npm member.
 79	    pub fn relative_path(&self) -> Option<&str> {
 80	        (self.suffix.starts_with("../") || self.suffix.starts_with("./")).then_some(self.suffix.as_str())
 81	    }
 82	
 83	    pub fn range(&self) -> Option<&str> {
 84	        if self.relative_path().is_some() {
 85	            return None;
 86	        }
 87	        let range = if self.alias().is_some() {
 88	            self.suffix.rsplit_once('@').map(|(_, range)| range)?
 89	        } else {
 90	            self.suffix.as_str()
 91	        };
 92	        (!matches!(range, "" | "*" | "^" | "~")).then_some(range)
 93	    }
 94	
 95	    /// Coverage assumes the workspace target has already been resolved locally.
 96	    pub fn coverage(&self, version: &Version) -> Result<Coverage, GrammarMismatch> {
 97	        let Some(range) = self.range() else {
 98	            return Ok(Coverage::Covers);
 99	        };
100	        // A full bare npm version is an exact pin, unlike Cargo's implicit caret.
101	        let requirement = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
102	            VersionReq::parse(&format!("={range}"), Ecosystem::Npm)
103	        } else if range.split('.').count() == 2
104	            && range
105	                .split('.')
106	                .all(|part| !part.is_empty() && part.bytes().all(|byte| byte.is_ascii_digit()))
107	        {
108	            VersionReq::parse(&format!("~{range}"), Ecosystem::Npm)
109	        } else {
110	            VersionReq::parse(range, Ecosystem::Npm)
111	        };
112	        match requirement {
113	            Ok(requirement) => Ok(if requirement.matches(version)? {
114	                Coverage::Covers
115	            } else {
116	                Coverage::DoesNotCover
117	            }),
118	            Err(_) => Ok(Coverage::Unknown),
119	        }
120	    }
121	
122	    pub fn with_range(&self, range: &str) -> Self {
123	        let suffix = match self.alias() {
124	            Some(target) => format!("{target}@{range}"),
125	            None => range.to_string(),
126	        };
127	        Self {
128	            kind: self.kind,
129	            suffix,
130	        }
131	    }
132	}
