551	fn assert_pnpm_protocols_and_pack(root: &Path, snapshot: bool) {
552	    let app_path = root.join("packages/app/package.json");
553	    let app = read_native_package(&app_path);
554	    let lib = read_native_package(&root.join("packages/lib/package.json"));
555	    let version = lib["version"].as_str().unwrap();
556	    if snapshot {
557	        assert!(version.starts_with("0.0.0-canary-"), "{version}");
558	    } else {
559	        assert_eq!(version, "0.3.0");
560	    }
561	    for (alias, suffix) in [("empty", ""), ("star", "*"), ("caret", "^"), ("tilde", "~")] {
562	        assert_eq!(app["dependencies"][alias], format!("workspace:@protocol/lib@{suffix}"));
563	    }
564	    assert_eq!(app["dependencies"]["path-lib"], "workspace:../lib");
565	    assert_eq!(
566	        app["dependencies"]["range"],
567	        format!("workspace:@protocol/lib@^{version}")
568	    );
569	    assert_eq!(app["dependencies"]["pin"], format!("workspace:@protocol/lib@{version}"));
570	    assert_eq!(
571	        app["devDependencies"]["dev-pin"],
572	        format!("workspace:@protocol/lib@{version}")
573	    );
574	    assert_eq!(app["optionalDependencies"]["optional"], "workspace:@protocol/lib@~");
575	    assert_eq!(app["optionalDependencies"]["private-leaf"], "workspace:*");
576	    assert_eq!(
577	        app["peerDependencies"]["@protocol/lib"],
578	        format!("workspace:^{version}")
579	    );
580	    assert_eq!(app["peerDependenciesMeta"]["@protocol/lib"]["optional"], true);
581	    let covered = if snapshot {
582	        format!(">={version}")
583	    } else {
584	        ">=0.2.0".to_string()
585	    };
586	    assert_eq!(
587	        app["dependencies"]["covered"],
588	        format!("workspace:@protocol/lib@{covered}")
589	    );
590	    let lock_before = fs::read(root.join("pnpm-lock.yaml")).unwrap();
591	    run_pnpm(root, &["install", "--frozen-lockfile", "--ignore-scripts", "--offline"]);
592	    assert_eq!(fs::read(root.join("pnpm-lock.yaml")).unwrap(), lock_before);
593	    let source_before = fs::read(&app_path).unwrap();
594	    let packed = packed_pnpm_manifest(root);
595	    assert_eq!(fs::read(&app_path).unwrap(), source_before);
596	    for (alias, prefix) in [
597	        ("empty", ""),
598	        ("star", ""),
599	        ("caret", "^"),
600	        ("tilde", "~"),
601	        ("path-lib", ""),
602	        ("pin", ""),
603	    ] {
604	        assert_eq!(
605	            packed["dependencies"][alias],
606	            format!("npm:@protocol/lib@{prefix}{version}")
607	        );
608	    }
609	    assert_eq!(packed["dependencies"]["range"], format!("npm:@protocol/lib@^{version}"));
610	    assert_eq!(
611	        packed["dependencies"]["covered"],
612	        format!("npm:@protocol/lib@{covered}")
613	    );
614	    assert_eq!(
615	        packed["optionalDependencies"]["optional"],
616	        format!("npm:@protocol/lib@~{version}")
617	    );
618	    let private = read_native_package(&root.join("packages/private-leaf/package.json"));
619	    assert_eq!(packed["optionalDependencies"]["private-leaf"], private["version"]);
620	    assert_eq!(packed["peerDependencies"]["@protocol/lib"], format!("^{version}"));
621	    assert_eq!(packed["peerDependenciesMeta"], app["peerDependenciesMeta"]);
622	}
